import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize highContrastMode state here
  const [highContrastMode, setHighContrastMode] = useState(false);

  // Define toggleHighContrast function here
  const toggleHighContrast = () => {
    setHighContrastMode(!highContrastMode);
  };

  return (
    <main>
      <h1>Accessibility (a11y) Fundamentals</h1>
      {/* Add your accessible button here */}
      <button onClick={toggleHighContrast}>
        {highContrastMode ? 'Disable High Contrast' : 'Enable High Contrast'}
      </button>
    </main>
  );
};

